output:
cat > forloop.yara << 'EOF'
rule ForLoop {
  strings:
    $a = { 90 90 }
    $b = { 0F 05 }
  condition:
    for any of ($a,$b) : ( @ > 0x2000 )
}
EOF

cat > var.yara << 'EOF'
rule VariableCheck {
  condition:
    uint32(0) == 0x464c457f
}
EOF

cat > offset_match.yara << 'EOF'
rule OffsetMatch {
  strings:
    $s = "critical"
  condition:
    @s == 0x100
}
EOF

cat > hex_pattern.yara << 'EOF'
rule HexPattern {
  strings:
    $hex = { 4D 5A 90 00 03 00 00 00 }
  condition:
    $hex
}
EOF
